def max_product(num_str, N, K):
    def get_product(num_str, N):
        return int(num_str) * N

    # case where no multiplication signs needed
    if K == 0:
        return get_product(num_str, N)

    # base case
    if N == 1:
        return get_product(num_str, N)

    # calculate the minimum product
    min_prod = get_product(num_str, N)

    # insert multiplication signs
    for i in range(K):
        # insert a multiplication sign at position i
        prod1 = get_product(num_str[:i] + "*" + num_str[i:], N)
        prod2 = get_product(num_str[:i] + "*" + num_str[i+1:], N-1)
        min_prod = min(min_prod, prod1, prod2)

    return min_prod
