def min_remaining_space(V, n, volumes):
    # Initialize a two-dimensional table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(V + 1)]

    # Fill in the table
    for i in range(1, V + 1):
        for j in range(1, n + 1):
            if i >= volumes[j - 1]:
                dp[i][j] = max(dp[i - volumes[j - 1]][j - 1], dp[i][j - 1])
            else:
                dp[i][j] = dp[i][j - 1]

    # Return the minimum remaining space
    return V - dp[V][n]
