        return 1

    # If a[n-1] is 0, then it is not possible to use the last flower type
    if a[n-1] == 0:
        return calculate_arrangements(n-1, m, a)

    # If m is less than a[n-1], then it is not possible to use the last flower type
    if m < a[n-1]:
        return calculate_arrangements(n-1, m, a)

    # If m is greater than a[n-1], then it is possible to use the last flower type
    # We can use the recurrence relation:
    # F(n, m) = F(n-1, m-a[n-1]) + F(n-1, m)
    return (calculate_arrangements(n-1, m-a[n-1], a) + calculate_arrangements(n-1, m, a)) % (10**6 + 7)

