def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0
    elif n == 1:
        return 0
    else:
        # Find the point where the heights start to decrease
        for i in range(n-1):
            if heights[i] > heights[i+1]:
                break
        # If the heights do not decrease, return 0
        if i == n-1:
            return 0
        # Otherwise, return the minimum number of students that need to leave
        return i + 1
